def comps(inp,v):
    H,W=len(inp),len(inp[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if inp[i][j]==v and (i,j) not in seen:
                q=[(i,j)]; seen.add((i,j)); cells=[]
                while q:
                    y,x=q.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and inp[ny][nx]==v:
                            seen.add((ny,nx)); q.append((ny,nx))
                out.append(cells)
    return out
